class Solution {
public:
    bool isBipartite(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<int> color(n, 0);
        for (int s = 0; s < n; s++) {
            if (color[s]) continue;
            queue<int> q;
            q.push(s);
            color[s] = 1;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                for (int v : graph[u]) {
                    if (color[v] == color[u]) return false;
                    if (!color[v]) {
                        color[v] = 3 - color[u];
                        q.push(v);
                    }
                }
            }
        }
        return true;
    }
};
